function who() {
  return this ? this.name : "none";
}
const inner = { name: "Inner", who };
const outer = { name: "Outer", inner };
const bound = who.bind({ name: "First" }).bind({ name: "Second" });
console.log(outer.inner.who());
console.log(bound());
console.log(bound.call(outer));
console.log(who.apply(outer));
